</input>
</sample_inputs>

Here is the source code:
<source_code>
#include <bits/stdc++.h>

#define ll long long
#define pb push_back
#define endl '\n'
#define pii pair<ll, ll>
#define vi vector<ll>
#define all(a) (a).begin(), (a).end()
#define F first
#define S second
#define sz(x) (ll)x.size()
#define rep(i, a, b) for (ll i = a; i < b; i++)

using namespace std;

void solve() {
    ll x, y, n;
    cin >> x >> y >> n;

    ll best_a = 0, best_b = 1;
    double target = (double)x / y;
    double min_diff = 1e18;

    rep(b, 1, n + 1) {
        // Find the best a for this denominator b
        ll a = (x * b + y / 2) / y; // rounding to nearest

        // Ensure a >= 0
        if (a < 0) a = 0;

        // Check a and a+1 (since rounding might not give the exact nearest)
        for (ll candidate_a : {a - 1, a, a + 1}) {
            if (candidate_a < 0) continue;

            double fraction = (double)candidate_a / b;
            double diff = fabs(fraction - target);

            // Update if this is closer, or same distance but smaller denominator, or same distance and denominator but smaller numerator
            if (diff < min_diff - 1e-12 || 
                (fabs(diff - min_diff) < 1e-12 && b < best_b) ||
                (fabs(diff - min_diff) < 1e-12 && b == best_b && candidate_a < best_a)) {
                min_diff = diff;
                best_a = candidate_a;
                best_b = b;
            }
        }
    }

    // Simplify the fraction
    ll g = __gcd(best_a, best_b);
    cout << best_a / g << '/' << best_b / g << endl;
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    ll test = 1;
    // cin >> test;
    while (test--) solve();
    return 0;
}
</source_code>
